/* KHBD Tin hoc Lop 5 KNTT (GDPT 2018) - soan cho But Xanh; PPCT theo KHGD mon Tin hoc 5 cua truong; tich hop Nang luc so (muc 2) + AI (muc nhan biet), kem canh bao an toan & dao duc so */
window.KHO_DATA_L5_TINHOC = [{"lop":5,"mon":"Tin học","tuan":1,"tiet":1,"bai":"Bài 1: Em có thể làm gì với máy tính? (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được một số công việc mà máy tính có thể hỗ trợ con người: soạn thảo, tính toán, vẽ, học tập, giải trí, tìm kiếm thông tin.\n- Nhận biết được máy tính là công cụ xử lí thông tin và giúp con người làm việc hiệu quả hơn.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem một số hình ảnh/đoạn phim ngắn về việc con người dùng máy tính trong học tập, công việc, đời sống.\n- Đặt câu hỏi: Em đã từng dùng máy tính để làm những việc gì?","hs":"- HS quan sát, kể lại những việc mình từng làm với máy tính (chơi, học, xem phim, tìm hình...)."},{"ten":"2. Khám phá: Máy tính hỗ trợ con người","gv":"- GV tổ chức nhóm tìm hiểu SGK: liệt kê các nhóm công việc máy tính có thể hỗ trợ (soạn thảo, tính toán, vẽ, tìm kiếm, học, giải trí).\n- Chốt: máy tính là công cụ xử lí thông tin.","hs":"- HS đọc SGK, thảo luận, ghép mỗi công việc với một phần mềm/ứng dụng phù hợp.\n- Ghi nhớ hộp kiến thức."},{"ten":"3. Khám phá: Lợi ích của máy tính","gv":"- GV nêu ví dụ so sánh làm việc có và không có máy tính (viết tay và soạn thảo, tính nhẩm và dùng bảng tính).\n- Chốt lợi ích: nhanh, chính xác, lưu trữ được.","hs":"- HS nêu thêm ví dụ về lợi ích của máy tính trong học tập của bản thân."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập nối/ghép công việc với công cụ, chọn Đúng – Sai (SGK).","hs":"- HS làm bài, chữa bài, giải thích lựa chọn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) GV hướng dẫn HS tự khởi động máy tính, mở đúng một ứng dụng học tập theo yêu cầu; quan sát HS thao tác.\n- (AI – mức nhận biết) GV giới thiệu ví dụ máy tính/điện thoại có trợ lí ảo giúp con người làm việc; nêu 1–2 việc trợ lí ảo có thể hỗ trợ.\n⚠ HS thao tác dưới sự giám sát của GV; không đăng nhập tài khoản cá nhân, không nhập thông tin riêng tư; dùng máy tính an toàn, đúng giờ, đúng mục đích học tập.","hs":"- HS tự khởi động máy, mở ứng dụng theo hướng dẫn; nêu nhận xét về việc máy tính/trợ lí ảo hỗ trợ con người; có ý thức sử dụng thiết bị số an toàn, tiết kiệm thời gian."}]},{"lop":5,"mon":"Tin học","tuan":2,"tiet":2,"bai":"Bài 1: Em có thể làm gì với máy tính? (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Kể được ví dụ cụ thể máy tính hỗ trợ học tập của bản thân.\n- Thực hành mở phần mềm, thao tác cơ bản để hoàn thành một nhiệm vụ đơn giản trên máy tính.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nhắc lại các công việc máy tính có thể hỗ trợ đã học ở tiết trước.","hs":"- HS trả lời nhanh, nhớ lại kiến thức."},{"ten":"2. Thực hành: Sử dụng máy tính hỗ trợ học tập","gv":"- GV giao nhiệm vụ: mở một phần mềm (soạn thảo/vẽ), thực hiện thao tác đơn giản theo mẫu.\n- Quan sát, hỗ trợ HS thao tác đúng.","hs":"- HS thực hành mở phần mềm, thao tác theo hướng dẫn, hoàn thành nhiệm vụ được giao."},{"ten":"3. Luyện tập","gv":"- GV cho HS trình bày sản phẩm đơn giản vừa làm; nhận xét, tuyên dương.","hs":"- HS trình bày, tự đánh giá và đánh giá bạn."},{"ten":"4. Vận dụng","gv":"- GV gợi ý: về nhà em có thể dùng máy tính (có người lớn hướng dẫn) để làm việc gì có ích cho học tập?","hs":"- HS nêu dự định vận dụng phù hợp lứa tuổi."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự thao tác lưu lại kết quả làm được vào đúng thư mục theo hướng dẫn.\n- (AI – mức nhận biết) GV cho HS quan sát tính năng gợi ý/tự sửa lỗi có sẵn trong phần mềm và giải thích đó là công cụ số hỗ trợ, không thay thế suy nghĩ của em.\n⚠ HS dùng máy tính đúng thời lượng, ngồi đúng tư thế, bảo vệ mắt; trung thực với sản phẩm của mình.","hs":"- HS lưu sản phẩm đúng nơi; nhận biết công cụ gợi ý của phần mềm; giữ tư thế ngồi đúng, dùng máy an toàn."}]},{"lop":5,"mon":"Tin học","tuan":3,"tiet":3,"bai":"Bài 2: Tìm kiếm thông tin trên website (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được website là nơi chứa thông tin trên Internet; nhận biết trình duyệt và địa chỉ website.\n- Thực hiện được thao tác mở trình duyệt, truy cập một website an toàn do GV chỉ định.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: muốn tìm hình ảnh về một con vật để làm bài, em tìm ở đâu?\n- Dẫn vào khái niệm website, Internet.","hs":"- HS thảo luận, nêu cách tìm thông tin (hỏi người lớn, tra Internet)."},{"ten":"2. Khám phá: Website và trình duyệt","gv":"- GV giới thiệu trình duyệt, thanh địa chỉ, cách nhập địa chỉ website.\n- Làm mẫu truy cập một website học tập an toàn.","hs":"- HS quan sát, nhận biết các thành phần trên trình duyệt; đọc SGK ghi nhớ."},{"ten":"3. Khám phá: Trang web chứa thông tin","gv":"- GV cho HS quan sát một trang web: có chữ, hình ảnh, liên kết.\n- Chốt: website là nơi chứa và cung cấp thông tin trên Internet.","hs":"- HS chỉ ra các dạng thông tin trên trang web đang xem."},{"ten":"4. Luyện tập – Thực hành","gv":"- GV cho HS thực hành mở trình duyệt, truy cập website do GV chỉ định (trong danh sách an toàn).","hs":"- HS thực hành truy cập đúng website, quan sát nội dung."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự nhập đúng địa chỉ website an toàn do GV cung cấp và truy cập.\n- (AI – nhận biết) GV giới thiệu ô tìm kiếm có gợi ý từ khoá tự động là một dạng công cụ thông minh; nhắc HS chỉ chọn kết quả phù hợp bài học.\n⚠ HS chỉ truy cập website GV cho phép; không nhấp vào quảng cáo, cửa sổ lạ; không cung cấp tên, địa chỉ, mật khẩu; báo GV khi thấy nội dung không phù hợp.","hs":"- HS truy cập đúng website an toàn; nhận biết ô tìm kiếm có gợi ý; thực hiện quy tắc an toàn khi lên mạng."}]},{"lop":5,"mon":"Tin học","tuan":4,"tiet":4,"bai":"Bài 2: Tìm kiếm thông tin trên website (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tìm kiếm thông tin đơn giản bằng từ khoá trên website/máy tìm kiếm do GV hướng dẫn.\n- Biết chọn lọc thông tin phù hợp, tôn trọng bản quyền và an toàn khi khai thác thông tin.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại cách truy cập website; nêu nhiệm vụ tìm thông tin cho bài học.","hs":"- HS nhớ lại thao tác mở trình duyệt, truy cập website."},{"ten":"2. Khám phá: Tìm kiếm bằng từ khoá","gv":"- GV hướng dẫn nhập từ khoá vào ô tìm kiếm, đọc kết quả, chọn trang phù hợp.\n- Làm mẫu với một từ khoá đơn giản.","hs":"- HS quan sát cách chọn từ khoá ngắn gọn, đúng nội dung cần tìm."},{"ten":"3. Thực hành: Tìm và chọn lọc thông tin","gv":"- GV giao nhiệm vụ tìm một thông tin phục vụ bài học; hướng dẫn chọn lọc, không chép nguyên văn.\n- Nhắc ghi nguồn khi sử dụng.","hs":"- HS thực hành tìm kiếm, chọn thông tin phù hợp, nêu nguồn lấy thông tin."},{"ten":"4. Vận dụng","gv":"- GV gợi ý: khi tìm được hình/ảnh trên mạng, vì sao cần xin phép hoặc ghi nguồn?","hs":"- HS trả lời, hiểu ý nghĩa tôn trọng bản quyền."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự nhập từ khoá và chọn được kết quả phù hợp; sao chép thông tin có ghi nguồn.\n- (AI – nhận biết) GV giới thiệu công cụ gợi ý kết quả tìm kiếm/gợi ý từ khoá là ứng dụng của trí tuệ nhân tạo, giúp tìm nhanh nhưng cần kiểm chứng thông tin.\n⚠ HS kiểm tra thông tin trước khi tin; không tải phần mềm lạ; tôn trọng bản quyền, ghi nguồn; giữ an toàn thông tin cá nhân.","hs":"- HS tìm kiếm và chọn lọc thông tin phù hợp; nhận biết vai trò của AI trong tìm kiếm; có ý thức kiểm chứng và ghi nguồn."}]},{"lop":5,"mon":"Tin học","tuan":5,"tiet":5,"bai":"Bài 3: Tìm kiếm thông tin trong giải quyết vấn đề (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được các bước tìm kiếm thông tin để giải quyết một vấn đề: xác định vấn đề, chọn từ khoá, tìm, chọn lọc.\n- Xác định được thông tin cần tìm cho một nhiệm vụ học tập cụ thể.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống thực tế: cần chuẩn bị bài giới thiệu về một địa danh, em cần tìm những thông tin gì?","hs":"- HS thảo luận, liệt kê thông tin cần tìm."},{"ten":"2. Khám phá: Các bước tìm kiếm thông tin","gv":"- GV hướng dẫn quy trình: xác định vấn đề → chọn từ khoá → tìm kiếm → chọn lọc → sử dụng.\n- Minh hoạ bằng ví dụ SGK.","hs":"- HS đọc SGK, nêu lại các bước; ghi nhớ hộp kiến thức."},{"ten":"3. Khám phá: Chọn từ khoá phù hợp","gv":"- GV phân tích cách chọn từ khoá ngắn, đúng trọng tâm; so sánh từ khoá tốt và chưa tốt.","hs":"- HS luyện chọn từ khoá cho một vài vấn đề GV nêu."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập xác định thông tin cần tìm và từ khoá tương ứng (SGK).","hs":"- HS làm bài, chữa bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự thực hiện một lượt tìm kiếm theo quy trình đã học với từ khoá tự chọn.\n- (AI – nhận biết) GV giới thiệu công cụ hỏi – đáp thông minh (chatbot) có thể gợi ý thông tin; nhấn mạnh phải kiểm chứng vì AI có thể trả lời sai.\n⚠ GV thao tác/kiểm soát công cụ AI; HS không tự đăng nhập; không tin ngay kết quả, luôn đối chiếu nguồn tin cậy; giữ an toàn thông tin.","hs":"- HS thực hiện quy trình tìm kiếm; nhận biết chatbot là công cụ AI cần kiểm chứng; hình thành thói quen đối chiếu thông tin."}]},{"lop":5,"mon":"Tin học","tuan":6,"tiet":6,"bai":"Bài 3: Tìm kiếm thông tin trong giải quyết vấn đề (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tìm kiếm, chọn lọc thông tin để giải quyết một vấn đề học tập.\n- Trình bày được kết quả tìm kiếm và nêu nguồn thông tin.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại quy trình tìm kiếm thông tin; giao nhiệm vụ nhóm.","hs":"- HS nhớ lại các bước, nhận nhiệm vụ."},{"ten":"2. Thực hành: Tìm kiếm giải quyết vấn đề","gv":"- GV giao mỗi nhóm một vấn đề nhỏ; hướng dẫn tìm, chọn lọc, ghi nguồn.\n- Quan sát, hỗ trợ.","hs":"- HS làm việc nhóm: chọn từ khoá, tìm, chọn thông tin phù hợp, ghi nguồn."},{"ten":"3. Luyện tập: Báo cáo kết quả","gv":"- GV tổ chức các nhóm báo cáo; nhận xét về cách chọn lọc và độ tin cậy thông tin.","hs":"- HS báo cáo, nêu nguồn; nhóm khác nhận xét."},{"ten":"4. Vận dụng","gv":"- GV gợi ý vận dụng tìm kiếm thông tin cho một môn học khác.","hs":"- HS nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tổng hợp thông tin tìm được thành một đoạn ngắn có ghi nguồn.\n- (AI – nhận biết) GV cho HS so sánh câu trả lời của chatbot với thông tin từ nguồn chính thống để thấy cần kiểm chứng.\n⚠ HS không sao chép nguyên văn từ AI; trung thực khi trình bày; tôn trọng bản quyền; bảo vệ thông tin cá nhân, không chia sẻ nội dung riêng tư lên mạng.","hs":"- HS tổng hợp thông tin có ghi nguồn; hiểu vì sao phải kiểm chứng thông tin từ AI; trung thực, tôn trọng bản quyền."}]},{"lop":5,"mon":"Tin học","tuan":7,"tiet":7,"bai":"Bài 4: Cây thư mục (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được cách tổ chức thông tin trong máy tính theo cây thư mục (thư mục, thư mục con, tệp).\n- Đọc và mô tả được cấu trúc một cây thư mục đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: tủ sách sắp xếp theo ngăn giúp tìm sách nhanh; máy tính lưu tệp thế nào cho dễ tìm?","hs":"- HS liên hệ cách sắp xếp đồ dùng, sách vở của mình."},{"ten":"2. Khám phá: Thư mục và tệp","gv":"- GV giới thiệu khái niệm tệp, thư mục, thư mục con; minh hoạ trên máy tính.\n- Chốt: thông tin được tổ chức theo cây thư mục.","hs":"- HS đọc SGK, phân biệt tệp và thư mục; ghi nhớ kiến thức."},{"ten":"3. Khám phá: Cấu trúc cây thư mục","gv":"- GV vẽ/minh hoạ một cây thư mục; hướng dẫn cách đọc đường dẫn.","hs":"- HS quan sát, mô tả cây thư mục mẫu, chỉ ra thư mục cha – con."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập đọc cây thư mục, xác định vị trí tệp (SGK).","hs":"- HS làm bài, chữa bài."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự mở cửa sổ quản lí tệp, quan sát và di chuyển trong cây thư mục theo hướng dẫn.\n- (AI – nhận biết) GV giới thiệu tính năng tìm kiếm tệp thông minh trên máy tính giúp tìm nhanh khi thư mục được đặt tên hợp lí.\n⚠ HS không xoá/di chuyển tệp của người khác; đặt tên thư mục rõ ràng; giữ gìn dữ liệu, không tự ý cài phần mềm.","hs":"- HS duyệt cây thư mục an toàn; nhận biết tính năng tìm kiếm tệp; có ý thức giữ gìn, sắp xếp dữ liệu gọn gàng."}]},{"lop":5,"mon":"Tin học","tuan":8,"tiet":8,"bai":"Bài 4: Cây thư mục (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tạo thư mục, thư mục con và sắp xếp tệp theo cây thư mục hợp lí.\n- Đặt tên thư mục, tệp rõ ràng để dễ tìm kiếm.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại khái niệm cây thư mục; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Tạo và sắp xếp thư mục","gv":"- GV hướng dẫn tạo thư mục, thư mục con, đổi tên; giao nhiệm vụ tổ chức tệp theo chủ đề.\n- Quan sát, hỗ trợ.","hs":"- HS thực hành tạo thư mục, đặt tên rõ ràng, sắp xếp tệp vào đúng thư mục."},{"ten":"3. Luyện tập","gv":"- GV kiểm tra cây thư mục HS tạo; nhận xét tính hợp lí, dễ tìm.","hs":"- HS trình bày cây thư mục của mình, tự đánh giá."},{"ten":"4. Vận dụng","gv":"- GV gợi ý: em sắp xếp thư mục bài học của mình ở nhà thế nào cho khoa học?","hs":"- HS nêu cách tổ chức thư mục học tập cá nhân."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tạo, đặt tên, sắp xếp thư mục và lưu tệp đúng vị trí.\n- (AI – nhận biết) GV cho HS dùng ô tìm kiếm của hệ điều hành để tìm nhanh một tệp; giải thích tên đặt hợp lí giúp công cụ tìm chính xác hơn.\n⚠ HS chỉ thao tác trên thư mục của mình; sao lưu cẩn thận; không xoá dữ liệu chung; giữ an toàn dữ liệu.","hs":"- HS tổ chức cây thư mục khoa học; sử dụng tìm kiếm tệp; hình thành thói quen quản lí dữ liệu gọn gàng, an toàn."}]},{"lop":5,"mon":"Tin học","tuan":9,"tiet":9,"bai":"Bài 5: Bản quyền nội dung thông tin (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là bản quyền nội dung thông tin; nhận biết hành vi tôn trọng và vi phạm bản quyền.\n- Giải thích được vì sao cần tôn trọng bản quyền khi sử dụng thông tin, hình ảnh, phần mềm.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: bạn A chép nguyên bài của bạn B rồi ghi tên mình. Việc đó đúng hay sai?","hs":"- HS thảo luận, bày tỏ ý kiến về tính trung thực."},{"ten":"2. Khám phá: Bản quyền là gì?","gv":"- GV giới thiệu khái niệm bản quyền, tác giả, sản phẩm trí tuệ (bài viết, tranh, nhạc, phần mềm).\n- Chốt: nội dung do người khác tạo ra được pháp luật bảo vệ.","hs":"- HS đọc SGK, nêu ví dụ sản phẩm có bản quyền; ghi nhớ kiến thức."},{"ten":"3. Khám phá: Tôn trọng bản quyền","gv":"- GV nêu các hành vi tôn trọng bản quyền: xin phép, ghi nguồn, không sao chép trái phép.\n- Phân biệt hành vi đúng – sai.","hs":"- HS phân loại tình huống tôn trọng/vi phạm bản quyền."},{"ten":"4. Luyện tập","gv":"- GV cho HS làm bài tập nhận xét hành vi liên quan bản quyền (SGK).","hs":"- HS làm bài, giải thích lựa chọn."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tìm một hình ảnh/nội dung được phép dùng miễn phí và ghi lại nguồn.\n- (AI – nhận biết) GV giới thiệu: nội dung do AI tạo ra (văn bản, hình ảnh) cũng cần ghi rõ là có sự hỗ trợ của AI và không mạo nhận là của mình.\n⚠ HS trung thực, ghi nguồn đầy đủ; không sao chép trái phép; không dùng sản phẩm của người khác để trục lợi; ứng xử có văn hoá trên mạng.","hs":"- HS tìm nội dung được phép dùng và ghi nguồn; hiểu cần minh bạch khi dùng AI; hình thành thái độ trung thực, tôn trọng bản quyền."}]},{"lop":5,"mon":"Tin học","tuan":10,"tiet":10,"bai":"Bài 5: Bản quyền nội dung thông tin (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được việc ghi nguồn khi sử dụng thông tin, hình ảnh của người khác.\n- Có thái độ ứng xử đúng mực, có văn hoá khi khai thác và chia sẻ thông tin trên môi trường số.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS nhắc lại khái niệm bản quyền và cách tôn trọng bản quyền.","hs":"- HS trả lời nhanh, nhớ lại kiến thức."},{"ten":"2. Thực hành: Ghi nguồn khi sử dụng thông tin","gv":"- GV hướng dẫn cách ghi nguồn cho hình ảnh/thông tin lấy từ Internet.\n- Giao bài tập nhỏ có sử dụng tư liệu.","hs":"- HS thực hành trích dẫn, ghi nguồn cho tư liệu đã dùng."},{"ten":"3. Luyện tập: Ứng xử có văn hoá","gv":"- GV nêu các tình huống chia sẻ thông tin trên mạng; hướng dẫn cách ứng xử đúng mực.","hs":"- HS thảo luận, chọn cách ứng xử có văn hoá, tôn trọng người khác."},{"ten":"4. Vận dụng","gv":"- GV gợi ý: khi làm bài có dùng hình trên mạng, em sẽ ghi nguồn thế nào?","hs":"- HS nêu cách ghi nguồn cho sản phẩm của mình."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện một sản phẩm nhỏ có ghi nguồn tư liệu đầy đủ.\n- (AI – nhận biết) GV nhắc: khi nhờ công cụ AI gợi ý ý tưởng, HS phải tự viết lại bằng lời của mình và kiểm tra tính đúng đắn, không sao chép máy móc.\n⚠ HS không chia sẻ thông tin cá nhân của mình và người khác; không đăng nội dung xúc phạm; ứng xử lịch sự, có trách nhiệm trên môi trường số.","hs":"- HS hoàn thiện sản phẩm có ghi nguồn; biết dùng gợi ý AI đúng cách; ứng xử văn minh, an toàn, có trách nhiệm trên mạng."}]},{"lop":5,"mon":"Tin học","tuan":11,"tiet":11,"bai":"Bài 6: Định dạng kí tự và bố trí hình ảnh trong văn bản (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được các thao tác định dạng kí tự: chọn phông chữ, cỡ chữ, kiểu chữ, màu chữ.\n- Thực hiện được định dạng kí tự cho một đoạn văn bản đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS so sánh hai văn bản: một chưa định dạng, một đã định dạng đẹp.\n- Hỏi: văn bản nào dễ đọc, hấp dẫn hơn? Vì sao?","hs":"- HS quan sát, nhận xét vai trò của việc định dạng."},{"ten":"2. Khám phá: Định dạng kí tự","gv":"- GV giới thiệu các nút định dạng: phông, cỡ, đậm, nghiêng, gạch chân, màu chữ.\n- Làm mẫu định dạng một đoạn.","hs":"- HS quan sát, nhận biết chức năng từng nút; đọc SGK."},{"ten":"3. Thực hành: Định dạng đoạn văn","gv":"- GV giao đoạn văn bản mẫu; hướng dẫn HS định dạng theo yêu cầu.\n- Quan sát, hỗ trợ.","hs":"- HS thực hành chọn phông, cỡ, kiểu, màu chữ cho đoạn văn bản."},{"ten":"4. Luyện tập","gv":"- GV yêu cầu HS định dạng một tiêu đề nổi bật; nhận xét kết quả.","hs":"- HS thực hiện, trình bày sản phẩm."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự chọn và áp dụng định dạng phù hợp cho văn bản theo yêu cầu.\n- (AI – nhận biết) GV giới thiệu tính năng kiểm tra chính tả/gợi ý sửa lỗi tự động trong phần mềm soạn thảo là công cụ hỗ trợ thông minh; HS vẫn cần tự đọc lại.\n⚠ HS lưu bài đúng thư mục; không thay đổi cài đặt máy; dùng máy đúng thời lượng, bảo vệ mắt.","hs":"- HS định dạng văn bản theo yêu cầu; nhận biết công cụ kiểm tra chính tả; có thói quen tự rà soát và lưu bài an toàn."}]},{"lop":5,"mon":"Tin học","tuan":12,"tiet":12,"bai":"Bài 6: Định dạng kí tự và bố trí hình ảnh trong văn bản (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được chèn và bố trí hình ảnh trong văn bản.\n- Trình bày được một văn bản có kênh chữ và kênh hình hài hoà, dễ đọc.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại định dạng kí tự; nêu nhiệm vụ chèn hình ảnh.","hs":"- HS nhớ lại thao tác định dạng."},{"ten":"2. Khám phá: Chèn và bố trí hình ảnh","gv":"- GV hướng dẫn chèn hình ảnh, thay đổi kích thước, vị trí, cách bố trí chữ quanh hình.\n- Làm mẫu.","hs":"- HS quan sát, nhận biết các thao tác với hình ảnh."},{"ten":"3. Thực hành: Trình bày văn bản có hình","gv":"- GV giao nhiệm vụ tạo văn bản ngắn có chữ và hình minh hoạ (dùng ảnh được phép, ghi nguồn).\n- Quan sát, hỗ trợ.","hs":"- HS thực hành chèn hình, sắp xếp hài hoà, hoàn thiện văn bản."},{"ten":"4. Vận dụng","gv":"- GV gợi ý: em có thể làm tấm thiệp/thông báo nhỏ trình bày đẹp.","hs":"- HS nêu ý tưởng sản phẩm vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự chèn hình được phép sử dụng và bố trí văn bản gọn gàng, có ghi nguồn hình.\n- (AI – nhận biết) GV giới thiệu công cụ gợi ý bố cục/mẫu thiết kế tự động; nhấn mạnh HS tự chọn cho phù hợp nội dung.\n⚠ HS chỉ dùng hình được phép, ghi nguồn; tôn trọng bản quyền; lưu và đặt tên tệp rõ ràng.","hs":"- HS trình bày văn bản có hình hài hoà; nhận biết gợi ý bố cục tự động; tôn trọng bản quyền hình ảnh."}]},{"lop":5,"mon":"Tin học","tuan":13,"tiet":13,"bai":"Bài 7: Thực hành soạn thảo văn bản (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được soạn thảo, chỉnh sửa và định dạng một văn bản hoàn chỉnh theo chủ đề.\n- Vận dụng các thao tác đã học để tạo sản phẩm số đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV giới thiệu nhiệm vụ dự án nhỏ: soạn một văn bản theo chủ đề gần gũi (giới thiệu quê hương, lớp học...).","hs":"- HS nghe, chọn chủ đề, hình dung nội dung."},{"ten":"2. Thực hành: Soạn thảo nội dung","gv":"- GV hướng dẫn HS gõ nội dung, chia đoạn hợp lí.\n- Quan sát, hỗ trợ gõ tiếng Việt.","hs":"- HS soạn thảo nội dung văn bản theo chủ đề đã chọn."},{"ten":"3. Thực hành: Định dạng và chỉnh sửa","gv":"- GV hướng dẫn HS định dạng kí tự, căn chỉnh, sửa lỗi.","hs":"- HS định dạng, chỉnh sửa cho văn bản rõ ràng, đẹp."},{"ten":"4. Luyện tập","gv":"- GV cho HS lưu và đặt tên tệp đúng quy định; kiểm tra tiến độ.","hs":"- HS lưu bài đúng thư mục, đặt tên rõ ràng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự soạn thảo, định dạng và lưu một văn bản hoàn chỉnh.\n- (AI – nhận biết) GV cho HS dùng công cụ kiểm tra chính tả để phát hiện lỗi; HS tự quyết định sửa hay không.\n⚠ HS trung thực với nội dung tự viết; nếu tham khảo tư liệu thì ghi nguồn; lưu bài an toàn, đúng thời lượng sử dụng máy.","hs":"- HS soạn thảo văn bản hoàn chỉnh; dùng công cụ kiểm tra chính tả có chọn lọc; trung thực, ghi nguồn khi tham khảo."}]},{"lop":5,"mon":"Tin học","tuan":14,"tiet":14,"bai":"Bài 7: Thực hành soạn thảo văn bản (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Hoàn thiện và trình bày được sản phẩm văn bản có chữ và hình ảnh.\n- Chia sẻ, nhận xét sản phẩm số của mình và của bạn.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại nhiệm vụ dự án; nêu tiêu chí sản phẩm đẹp, rõ ràng.","hs":"- HS nhớ lại tiêu chí, tiếp tục hoàn thiện."},{"ten":"2. Thực hành: Hoàn thiện sản phẩm","gv":"- GV hướng dẫn HS chèn hình minh hoạ, rà soát lỗi, hoàn thiện bố cục.\n- Quan sát, hỗ trợ.","hs":"- HS hoàn thiện văn bản: chèn hình, định dạng, sửa lỗi."},{"ten":"3. Luyện tập: Trưng bày sản phẩm","gv":"- GV tổ chức trưng bày/giới thiệu sản phẩm; hướng dẫn nhận xét theo tiêu chí.","hs":"- HS giới thiệu sản phẩm; nhận xét bài bạn một cách tích cực."},{"ten":"4. Vận dụng","gv":"- GV gợi ý dùng kĩ năng soạn thảo cho các môn học khác hoặc việc ở nhà.","hs":"- HS nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện, lưu và (nếu có điều kiện) chia sẻ sản phẩm số trong lớp.\n- (AI – nhận biết) GV giới thiệu công cụ AI có thể gợi ý ý tưởng trình bày; HS tham khảo rồi tự quyết định, không lệ thuộc.\n⚠ HS ghi nguồn hình, tôn trọng bản quyền; nhận xét bạn có văn hoá; không chia sẻ thông tin cá nhân ra ngoài.","hs":"- HS hoàn thiện và chia sẻ sản phẩm; biết tham khảo gợi ý của AI có chọn lọc; ứng xử tích cực, tôn trọng bản quyền."}]},{"lop":5,"mon":"Tin học","tuan":15,"tiet":15,"bai":"Bài 8A: Làm quen với phần mềm đồ hoạ (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được công dụng của phần mềm đồ hoạ; nhận biết các công cụ vẽ cơ bản.\n- Thực hiện được thao tác vẽ hình đơn giản bằng công cụ đường thẳng, hình khối, tô màu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV cho HS xem một số tranh vẽ trên máy tính; hỏi các bức tranh này được tạo bằng gì?","hs":"- HS quan sát, nêu suy nghĩ về vẽ tranh trên máy tính."},{"ten":"2. Khám phá: Phần mềm đồ hoạ và công cụ vẽ","gv":"- GV giới thiệu giao diện phần mềm đồ hoạ, các công cụ: bút, đường thẳng, hình, tô màu.\n- Làm mẫu vẽ hình cơ bản.","hs":"- HS quan sát, nhận biết các công cụ; đọc SGK."},{"ten":"3. Thực hành: Vẽ hình đơn giản","gv":"- GV giao nhiệm vụ vẽ một hình đơn giản (nhà, cây, mặt trời) bằng công cụ cơ bản.\n- Quan sát, hỗ trợ.","hs":"- HS thực hành vẽ, tô màu hình theo yêu cầu."},{"ten":"4. Luyện tập","gv":"- GV cho HS lưu tranh; nhận xét sản phẩm.","hs":"- HS lưu tranh đúng thư mục, trình bày."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự chọn công cụ vẽ và tạo một hình đơn giản, lưu lại đúng nơi.\n- (AI – nhận biết) GV giới thiệu một số phần mềm/công cụ có thể tạo hình ảnh từ mô tả bằng lời (AI tạo ảnh); nhấn mạnh đây là công cụ hỗ trợ, HS vẫn cần tự sáng tạo và ghi rõ khi dùng AI.\n⚠ GV kiểm soát công cụ AI; HS không nhập thông tin cá nhân; trung thực, không mạo nhận sản phẩm AI là của mình.","hs":"- HS vẽ và lưu hình đơn giản; nhận biết công cụ AI tạo ảnh; giữ thái độ trung thực, sáng tạo."}]},{"lop":5,"mon":"Tin học","tuan":16,"tiet":16,"bai":"Bài 8A: Làm quen với phần mềm đồ hoạ (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được vẽ, chỉnh sửa và hoàn thiện một sản phẩm đồ hoạ theo ý tưởng.\n- Trình bày và chia sẻ được sản phẩm số của mình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại các công cụ vẽ; nêu nhiệm vụ sáng tạo bức tranh theo chủ đề.","hs":"- HS nhớ lại công cụ, chọn ý tưởng tranh."},{"ten":"2. Thực hành: Vẽ tranh theo chủ đề","gv":"- GV hướng dẫn HS phối hợp các công cụ để vẽ tranh; gợi ý bố cục, màu sắc.\n- Quan sát, hỗ trợ.","hs":"- HS thực hành vẽ tranh theo ý tưởng, chỉnh sửa cho đẹp."},{"ten":"3. Luyện tập: Hoàn thiện và lưu","gv":"- GV hướng dẫn HS chỉnh sửa chi tiết, lưu và đặt tên tệp.","hs":"- HS hoàn thiện tranh, lưu đúng thư mục."},{"ten":"4. Vận dụng","gv":"- GV tổ chức trưng bày tranh; gợi ý dùng phần mềm đồ hoạ minh hoạ cho bài học khác.","hs":"- HS giới thiệu tranh; nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện một sản phẩm đồ hoạ theo ý tưởng và chia sẻ trong lớp.\n- (AI – nhận biết) GV cho HS quan sát cách công cụ AI gợi ý màu/hiệu ứng; HS tự quyết định giữ hay đổi cho phù hợp ý tưởng.\n⚠ HS trung thực về phần mình tự làm; tôn trọng sản phẩm của bạn; dùng máy đúng thời lượng, bảo vệ mắt.","hs":"- HS hoàn thiện và chia sẻ tranh; biết chọn lọc gợi ý của AI; trung thực, tôn trọng sản phẩm của bạn."}]},{"lop":5,"mon":"Tin học","tuan":17,"tiet":17,"bai":"Ôn tập học kì I","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá kiến thức, kĩ năng đã học: máy tính và em, tìm kiếm thông tin trên website, tổ chức lưu trữ thông tin, bản quyền, soạn thảo văn bản, phần mềm đồ hoạ.\n- Vận dụng làm bài ôn tập và tự đánh giá kết quả học tập.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi hỏi – đáp nhanh ôn lại kiến thức các chủ đề học kì I.","hs":"- HS tham gia trả lời, nhớ lại kiến thức."},{"ten":"2. Ôn tập kiến thức","gv":"- GV hệ thống kiến thức trọng tâm bằng sơ đồ tư duy/bảng tổng hợp.","hs":"- HS nhắc lại các đơn vị kiến thức; nêu ví dụ minh hoạ."},{"ten":"3. Luyện tập tổng hợp","gv":"- GV cho HS làm phiếu ôn tập (trắc nghiệm + thực hành ngắn nếu có phòng máy): tìm kiếm, tổ chức thư mục, soạn thảo, vẽ.","hs":"- HS làm bài, tự đánh giá và đánh giá bạn."},{"ten":"4. Vận dụng","gv":"- GV gợi ý HS nêu những kĩ năng tin học đã dùng được trong học tập và đời sống.","hs":"- HS chia sẻ trải nghiệm vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự thực hiện lại một số thao tác trọng tâm: tìm kiếm an toàn, tạo thư mục, soạn thảo, lưu tệp.\n- (AI – nhận biết) GV hệ thống lại: AI là công cụ hỗ trợ (gợi ý từ khoá, kiểm tra chính tả, tạo ảnh...) nhưng cần kiểm chứng và dùng trung thực.\n⚠ Nhắc lại quy tắc an toàn: bảo vệ thông tin cá nhân, tôn trọng bản quyền, ứng xử có văn hoá, dùng máy đúng thời lượng.","hs":"- HS ôn lại thao tác trọng tâm; củng cố hiểu biết về vai trò và giới hạn của AI; ghi nhớ quy tắc an toàn số."}]},{"lop":5,"mon":"Tin học","tuan":18,"tiet":18,"bai":"Kiểm tra học kì I","yccd":"1. Năng lực Tin học (đặc thù):\n- Đánh giá được mức độ đạt yêu cầu cần đạt của học kì I về kiến thức, kĩ năng tin học.\n- Vận dụng độc lập, trung thực làm bài kiểm tra.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Hướng dẫn","gv":"- GV phổ biến hình thức, thời gian, yêu cầu bài kiểm tra (trắc nghiệm và/hoặc thực hành).","hs":"- HS lắng nghe, chuẩn bị làm bài."},{"ten":"2. Kiểm tra","gv":"- GV phát đề/giao nhiệm vụ thực hành; theo dõi, bảo đảm nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài/sản phẩm; nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài; rút kinh nghiệm."},{"ten":"4. Vận dụng","gv":"- GV gợi ý HS tiếp tục rèn kĩ năng tin học đã học ở nhà một cách an toàn.","hs":"- HS nêu dự định rèn luyện."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự thao tác trên máy để hoàn thành phần thực hành (nếu có), lưu bài đúng quy định.\n- (AI – nhận biết) GV nhắc: khi kiểm tra, HS không dùng công cụ AI để làm thay; phải tự lực, trung thực.\n⚠ Đề cao tính trung thực; không sao chép; giữ an toàn dữ liệu bài làm; dùng máy đúng mục đích.","hs":"- HS hoàn thành bài kiểm tra trung thực; không lệ thuộc công cụ AI; giữ an toàn dữ liệu."}]},{"lop":5,"mon":"Tin học","tuan":19,"tiet":19,"bai":"Bài 9A: Sử dụng phần mềm đồ hoạ tạo sản phẩm số","yccd":"1. Năng lực Tin học (đặc thù):\n- Vận dụng phần mềm đồ hoạ để tạo một sản phẩm số hoàn chỉnh theo chủ đề.\n- Trình bày, chia sẻ và tự đánh giá được sản phẩm số của mình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV giới thiệu nhiệm vụ: dùng phần mềm đồ hoạ tạo một sản phẩm (thiệp, tranh cổ động, minh hoạ bài học).","hs":"- HS chọn chủ đề, hình dung sản phẩm."},{"ten":"2. Thực hành: Tạo sản phẩm số","gv":"- GV hướng dẫn HS phối hợp công cụ vẽ, chèn chữ, màu sắc để tạo sản phẩm.\n- Quan sát, hỗ trợ.","hs":"- HS thực hành tạo sản phẩm theo ý tưởng."},{"ten":"3. Luyện tập: Hoàn thiện và lưu","gv":"- GV hướng dẫn chỉnh sửa, lưu, đặt tên tệp.","hs":"- HS hoàn thiện, lưu sản phẩm đúng thư mục."},{"ten":"4. Vận dụng – Chia sẻ","gv":"- GV tổ chức trưng bày; hướng dẫn nhận xét theo tiêu chí.","hs":"- HS giới thiệu sản phẩm; nhận xét bài bạn tích cực."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tạo và hoàn thiện một sản phẩm số theo chủ đề, chia sẻ trong lớp.\n- (AI – nhận biết) GV cho HS quan sát công cụ AI gợi ý mẫu/hiệu ứng; HS tự chọn cho phù hợp và ghi rõ nếu có dùng AI.\n⚠ HS dùng tư liệu được phép, ghi nguồn; trung thực về phần tự làm; tôn trọng bản quyền và sản phẩm của bạn.","hs":"- HS tạo sản phẩm số hoàn chỉnh; biết dùng gợi ý AI có chọn lọc và minh bạch; tôn trọng bản quyền."}]},{"lop":5,"mon":"Tin học","tuan":20,"tiet":20,"bai":"Bài 10: Cấu trúc tuần tự (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là cấu trúc tuần tự: các bước thực hiện lần lượt theo thứ tự.\n- Mô tả được một công việc quen thuộc dưới dạng dãy các bước tuần tự.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu ví dụ pha một cốc nước cam/đánh răng; hỏi các bước phải làm theo thứ tự nào?","hs":"- HS sắp xếp các bước theo đúng thứ tự."},{"ten":"2. Khám phá: Cấu trúc tuần tự","gv":"- GV giới thiệu khái niệm cấu trúc tuần tự trong chương trình: các lệnh thực hiện lần lượt.\n- Minh hoạ trên môi trường lập trình trực quan (kéo thả).","hs":"- HS đọc SGK, nhận biết dãy lệnh tuần tự; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Tạo dãy lệnh tuần tự","gv":"- GV hướng dẫn HS ghép các khối lệnh theo thứ tự để nhân vật thực hiện một hành động đơn giản.\n- Quan sát, hỗ trợ.","hs":"- HS kéo thả khối lệnh tạo chương trình tuần tự đơn giản, chạy thử."},{"ten":"4. Luyện tập","gv":"- GV cho HS sửa thứ tự lệnh để đạt kết quả đúng; nhận xét.","hs":"- HS chỉnh sửa, chạy thử, giải thích."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự ghép và chạy thử một chương trình tuần tự đơn giản trên môi trường lập trình trực quan.\n- (AI – nhận biết) GV giới thiệu: nhiều thiết bị thông minh hoạt động theo chương trình do con người viết; máy tính làm đúng những gì được lập trình theo thứ tự.\n⚠ HS thao tác trên phần mềm học tập an toàn; kiên nhẫn sửa lỗi; không tự cài phần mềm lạ.","hs":"- HS tạo và chạy chương trình tuần tự; hiểu máy tính/thiết bị hoạt động theo chương trình; rèn tính cẩn thận."}]},{"lop":5,"mon":"Tin học","tuan":21,"tiet":21,"bai":"Bài 10: Cấu trúc tuần tự (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tạo và chạy một chương trình có cấu trúc tuần tự để giải quyết nhiệm vụ cụ thể.\n- Phát hiện và sửa được lỗi thứ tự lệnh trong chương trình đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại cấu trúc tuần tự; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Lập trình tuần tự","gv":"- GV giao nhiệm vụ điều khiển nhân vật hoàn thành một chặng đường/hình vẽ bằng dãy lệnh tuần tự.\n- Quan sát, hỗ trợ.","hs":"- HS ghép khối lệnh, chạy thử, điều chỉnh cho đúng."},{"ten":"3. Luyện tập: Sửa lỗi chương trình","gv":"- GV đưa chương trình sai thứ tự; hướng dẫn HS phát hiện và sửa.","hs":"- HS tìm lỗi, sắp xếp lại lệnh, chạy thử lại."},{"ten":"4. Vận dụng","gv":"- GV gợi ý mô tả một việc hằng ngày dưới dạng dãy bước tuần tự.","hs":"- HS nêu ví dụ dãy bước tuần tự trong đời sống."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự phát hiện, sửa lỗi và hoàn thiện một chương trình tuần tự.\n- (AI – nhận biết) GV giới thiệu công cụ gợi ý sửa lỗi/hoàn thiện mã trong một số phần mềm; nhấn mạnh HS cần hiểu chương trình của mình, không phụ thuộc hoàn toàn.\n⚠ HS kiên trì thử – sai; giữ an toàn dữ liệu; dùng máy đúng thời lượng.","hs":"- HS sửa lỗi và hoàn thiện chương trình; nhận biết công cụ gợi ý sửa lỗi; rèn tính kiên trì, tự lực."}]},{"lop":5,"mon":"Tin học","tuan":22,"tiet":22,"bai":"Bài 11: Cấu trúc lặp (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là cấu trúc lặp: lặp lại một hoặc nhiều lệnh nhiều lần.\n- Nhận biết được tình huống có thể dùng lặp để rút gọn chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu ví dụ: vẽ 4 cạnh hình vuông phải làm lại thao tác giống nhau nhiều lần.\n- Hỏi: có cách nào ngắn gọn hơn không?","hs":"- HS nhận ra việc lặp lại thao tác giống nhau."},{"ten":"2. Khám phá: Cấu trúc lặp","gv":"- GV giới thiệu khối lệnh lặp; giải thích số lần lặp.\n- So sánh chương trình có lặp và không lặp.","hs":"- HS đọc SGK, nhận biết khối lệnh lặp; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Dùng lệnh lặp","gv":"- GV hướng dẫn HS dùng lệnh lặp để vẽ hình đơn giản (hình vuông, tam giác).\n- Quan sát, hỗ trợ.","hs":"- HS ghép khối lệnh lặp, chạy thử, quan sát kết quả."},{"ten":"4. Luyện tập","gv":"- GV cho HS thay đổi số lần lặp và dự đoán kết quả.","hs":"- HS thử nghiệm, giải thích kết quả."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự dùng lệnh lặp tạo chương trình vẽ hình và chạy thử.\n- (AI – nhận biết) GV liên hệ: các thiết bị tự động (robot hút bụi, dây chuyền) lặp lại thao tác theo chương trình; máy làm việc theo quy tắc con người đặt ra.\n⚠ HS thao tác trên phần mềm an toàn; cẩn thận khi đặt số lần lặp; không cài phần mềm lạ.","hs":"- HS dùng lệnh lặp tạo chương trình; liên hệ cấu trúc lặp với thiết bị tự động; rèn tư duy tối ưu."}]},{"lop":5,"mon":"Tin học","tuan":23,"tiet":23,"bai":"Bài 11: Cấu trúc lặp (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tạo chương trình có cấu trúc lặp để giải quyết nhiệm vụ.\n- So sánh được chương trình dùng lặp và không dùng lặp về độ gọn, dễ hiểu.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại cấu trúc lặp; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Lập trình với lặp","gv":"- GV giao nhiệm vụ vẽ hoa văn/đa giác bằng lệnh lặp.\n- Quan sát, hỗ trợ.","hs":"- HS ghép lệnh lặp, chạy thử, điều chỉnh số lần lặp cho đúng."},{"ten":"3. Luyện tập: So sánh chương trình","gv":"- GV cho HS so sánh chương trình có lặp và không lặp cho cùng kết quả.","hs":"- HS nhận xét chương trình nào gọn, dễ hiểu hơn."},{"ten":"4. Vận dụng","gv":"- GV gợi ý nêu ví dụ công việc lặp lại trong đời sống có thể tự động hoá.","hs":"- HS nêu ví dụ vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tối ưu một chương trình bằng cách dùng lệnh lặp thay cho các lệnh lặp lại.\n- (AI – nhận biết) GV nêu: nhiều ứng dụng thông minh xử lí công việc lặp đi lặp lại nhanh và chính xác nhờ chương trình.\n⚠ HS kiểm tra kĩ trước khi chạy; giữ an toàn dữ liệu; dùng máy đúng thời lượng.","hs":"- HS tối ưu chương trình bằng lệnh lặp; hiểu lợi ích của tự động hoá; rèn tư duy giải quyết vấn đề."}]},{"lop":5,"mon":"Tin học","tuan":24,"tiet":24,"bai":"Bài 12: Thực hành sử dụng lệnh lặp (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Vận dụng lệnh lặp để tạo chương trình giải quyết một nhiệm vụ cụ thể.\n- Rèn kĩ năng ghép lệnh, chạy thử và điều chỉnh chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu nhiệm vụ thực hành: tạo chương trình vẽ/di chuyển có sử dụng lặp.","hs":"- HS hình dung nhiệm vụ, chuẩn bị thực hành."},{"ten":"2. Thực hành: Ghép và chạy chương trình","gv":"- GV hướng dẫn HS phân tích nhiệm vụ, xác định phần lặp lại, ghép lệnh lặp.\n- Quan sát, hỗ trợ.","hs":"- HS ghép lệnh lặp, chạy thử chương trình."},{"ten":"3. Luyện tập: Điều chỉnh chương trình","gv":"- GV cho HS thay đổi tham số (số lần lặp, bước di chuyển) để đạt kết quả mong muốn.","hs":"- HS điều chỉnh, quan sát và giải thích kết quả."},{"ten":"4. Vận dụng","gv":"- GV gợi ý tạo thêm một biến thể của chương trình.","hs":"- HS thử tạo biến thể."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự phân tích nhiệm vụ, dùng lệnh lặp và chạy thử để hoàn thành.\n- (AI – nhận biết) GV giới thiệu môi trường lập trình có gợi ý khối lệnh phù hợp; HS tham khảo nhưng tự lựa chọn.\n⚠ HS thao tác an toàn; kiên nhẫn thử – sửa; giữ an toàn dữ liệu; đúng thời lượng dùng máy.","hs":"- HS dùng lệnh lặp giải quyết nhiệm vụ; biết dùng gợi ý khối lệnh có chọn lọc; rèn tính kiên trì."}]},{"lop":5,"mon":"Tin học","tuan":25,"tiet":25,"bai":"Bài 12: Thực hành sử dụng lệnh lặp (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Hoàn thiện được một chương trình sử dụng lệnh lặp cho sản phẩm cụ thể.\n- Phát hiện, sửa lỗi và trình bày được chương trình của mình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại nhiệm vụ; nêu tiêu chí chương trình hoàn thiện.","hs":"- HS nhớ lại tiêu chí, tiếp tục hoàn thiện."},{"ten":"2. Thực hành: Hoàn thiện chương trình","gv":"- GV hướng dẫn HS bổ sung, chỉnh sửa để chương trình chạy đúng, đẹp.\n- Quan sát, hỗ trợ.","hs":"- HS hoàn thiện chương trình, chạy thử nhiều lần."},{"ten":"3. Luyện tập: Sửa lỗi và trình bày","gv":"- GV cho HS phát hiện, sửa lỗi; tổ chức trình bày chương trình.","hs":"- HS sửa lỗi, giới thiệu chương trình, giải thích cách làm."},{"ten":"4. Vận dụng","gv":"- GV gợi ý áp dụng lệnh lặp vào một ý tưởng của HS.","hs":"- HS nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện, sửa lỗi và trình bày một chương trình dùng lệnh lặp.\n- (AI – nhận biết) GV cho HS quan sát công cụ gợi ý sửa lỗi; nhấn mạnh HS phải hiểu và tự kiểm tra chương trình.\n⚠ HS trung thực về phần mình làm; tôn trọng sản phẩm của bạn; giữ an toàn dữ liệu.","hs":"- HS hoàn thiện và trình bày chương trình; dùng gợi ý sửa lỗi có kiểm soát; trung thực, tự lực."}]},{"lop":5,"mon":"Tin học","tuan":26,"tiet":26,"bai":"Bài 13: Cấu trúc rẽ nhánh (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là cấu trúc rẽ nhánh: thực hiện lệnh tuỳ theo điều kiện đúng hay sai.\n- Nhận biết được tình huống cần dùng rẽ nhánh trong đời sống và trong chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu tình huống: nếu trời mưa thì mang ô, nếu không thì đội mũ.\n- Hỏi: quyết định phụ thuộc vào điều gì?","hs":"- HS nhận ra hành động phụ thuộc vào điều kiện."},{"ten":"2. Khám phá: Cấu trúc rẽ nhánh","gv":"- GV giới thiệu khối lệnh điều kiện (nếu... thì..., nếu... thì... nếu không...).\n- Minh hoạ trên môi trường lập trình.","hs":"- HS đọc SGK, nhận biết khối lệnh rẽ nhánh; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Dùng lệnh rẽ nhánh","gv":"- GV hướng dẫn HS tạo chương trình để nhân vật phản ứng khác nhau theo điều kiện.\n- Quan sát, hỗ trợ.","hs":"- HS ghép khối lệnh điều kiện, chạy thử."},{"ten":"4. Luyện tập","gv":"- GV cho HS dự đoán kết quả chương trình theo từng điều kiện.","hs":"- HS dự đoán, chạy thử, kiểm chứng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tạo chương trình có rẽ nhánh đơn giản và chạy thử với các điều kiện khác nhau.\n- (AI – nhận biết) GV liên hệ: trợ lí ảo/ứng dụng thông minh đưa ra phản hồi khác nhau tuỳ câu hỏi/điều kiện, đó là ứng dụng của rẽ nhánh.\n⚠ HS thao tác an toàn; kiểm tra kĩ điều kiện; giữ an toàn dữ liệu; không cài phần mềm lạ.","hs":"- HS tạo chương trình rẽ nhánh; liên hệ với ứng dụng thông minh; rèn tư duy điều kiện – lựa chọn."}]},{"lop":5,"mon":"Tin học","tuan":27,"tiet":27,"bai":"Bài 13: Cấu trúc rẽ nhánh (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Thực hiện được tạo chương trình có cấu trúc rẽ nhánh để giải quyết nhiệm vụ.\n- Phát hiện, sửa lỗi điều kiện và trình bày chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại cấu trúc rẽ nhánh; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Lập trình rẽ nhánh","gv":"- GV giao nhiệm vụ (trò chơi đúng/sai, cho điểm theo điều kiện...).\n- Quan sát, hỗ trợ.","hs":"- HS ghép khối điều kiện, chạy thử, điều chỉnh."},{"ten":"3. Luyện tập: Sửa lỗi điều kiện","gv":"- GV đưa chương trình có điều kiện sai; hướng dẫn HS phát hiện, sửa.","hs":"- HS tìm và sửa lỗi điều kiện, chạy thử lại."},{"ten":"4. Vận dụng","gv":"- GV gợi ý nêu ví dụ quyết định theo điều kiện trong học tập/sinh hoạt.","hs":"- HS nêu ví dụ vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện chương trình rẽ nhánh, kiểm tra kết quả với nhiều điều kiện.\n- (AI – nhận biết) GV nêu: chương trình máy tính và AI xử lí tình huống dựa trên các điều kiện; kết quả phụ thuộc dữ liệu và quy tắc.\n⚠ HS trung thực, tự lực; giữ an toàn dữ liệu; dùng máy đúng thời lượng.","hs":"- HS hoàn thiện chương trình rẽ nhánh; hiểu vai trò điều kiện trong AI; rèn tư duy logic."}]},{"lop":5,"mon":"Tin học","tuan":28,"tiet":28,"bai":"Bài 14: Sử dụng biến trong chương trình (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là biến trong chương trình: nơi lưu và thay đổi giá trị.\n- Thực hiện được tạo biến và gán giá trị cho biến trong chương trình đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu ví dụ ghi điểm trò chơi: số điểm thay đổi trong khi chơi.\n- Hỏi: máy tính lưu số điểm ở đâu?","hs":"- HS liên hệ việc lưu và thay đổi giá trị."},{"ten":"2. Khám phá: Biến trong chương trình","gv":"- GV giới thiệu khái niệm biến; cách tạo biến và gán giá trị.\n- Minh hoạ trên môi trường lập trình.","hs":"- HS đọc SGK, nhận biết biến; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Tạo và dùng biến","gv":"- GV hướng dẫn HS tạo biến, đặt tên, gán và thay đổi giá trị.\n- Quan sát, hỗ trợ.","hs":"- HS tạo biến, gán giá trị, chạy thử quan sát thay đổi."},{"ten":"4. Luyện tập","gv":"- GV cho HS tạo chương trình đếm/tính điểm dùng biến.","hs":"- HS thực hành, chạy thử, giải thích."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tạo biến và dùng biến trong một chương trình đơn giản (tích hợp STEM: lập trình trò chơi).\n- (AI – nhận biết) GV nêu: nhiều ứng dụng thông minh ghi nhớ và cập nhật dữ liệu (điểm, tiến độ) nhờ biến trong chương trình.\n⚠ HS đặt tên biến rõ ràng; thao tác an toàn; giữ an toàn dữ liệu; đúng thời lượng dùng máy.","hs":"- HS tạo và dùng biến trong chương trình; liên hệ với ứng dụng ghi nhớ dữ liệu; rèn tư duy trừu tượng."}]},{"lop":5,"mon":"Tin học","tuan":29,"tiet":29,"bai":"Bài 14: Sử dụng biến trong chương trình (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Vận dụng biến để tạo chương trình có ghi nhớ, cập nhật giá trị (đếm, tính điểm).\n- Phát hiện, sửa lỗi và trình bày được chương trình sử dụng biến.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại khái niệm biến; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Lập trình có biến","gv":"- GV giao nhiệm vụ tạo trò chơi/chương trình có tính điểm hoặc đếm.\n- Quan sát, hỗ trợ.","hs":"- HS tạo chương trình dùng biến, chạy thử."},{"ten":"3. Luyện tập: Sửa lỗi và hoàn thiện","gv":"- GV hướng dẫn HS phát hiện lỗi cập nhật biến; hoàn thiện chương trình.","hs":"- HS sửa lỗi, hoàn thiện, trình bày chương trình."},{"ten":"4. Vận dụng","gv":"- GV gợi ý ý tưởng dùng biến cho một chương trình khác.","hs":"- HS nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện một chương trình dùng biến để giải quyết nhiệm vụ.\n- (AI – nhận biết) GV cho HS thấy các ứng dụng theo dõi tiến độ học tập cập nhật số liệu tự động nhờ biến và chương trình.\n⚠ HS trung thực về phần mình làm; tôn trọng sản phẩm của bạn; giữ an toàn dữ liệu.","hs":"- HS hoàn thiện chương trình dùng biến; liên hệ ứng dụng thực tế; trung thực, tự lực."}]},{"lop":5,"mon":"Tin học","tuan":30,"tiet":30,"bai":"Bài 15: Sử dụng biểu thức trong chương trình (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được thế nào là biểu thức: kết hợp các giá trị, biến và phép toán để tính kết quả.\n- Thực hiện được sử dụng biểu thức số học đơn giản trong chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nêu ví dụ tính tổng điểm hai vòng chơi: cộng hai số.\n- Hỏi: máy tính tính tổng bằng cách nào?","hs":"- HS liên hệ phép tính với chương trình."},{"ten":"2. Khám phá: Biểu thức trong chương trình","gv":"- GV giới thiệu biểu thức số học (cộng, trừ, nhân, chia) dùng biến và giá trị.\n- Minh hoạ trên môi trường lập trình.","hs":"- HS đọc SGK, nhận biết biểu thức; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Dùng biểu thức","gv":"- GV hướng dẫn HS tạo chương trình tính toán bằng biểu thức (tính tổng, hiệu...).\n- Quan sát, hỗ trợ.","hs":"- HS ghép lệnh dùng biểu thức, chạy thử, kiểm tra kết quả."},{"ten":"4. Luyện tập","gv":"- GV cho HS thay đổi giá trị và dự đoán kết quả biểu thức.","hs":"- HS thử nghiệm, giải thích kết quả."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự dùng biểu thức trong một chương trình tính toán đơn giản.\n- (AI – nhận biết) GV giới thiệu công cụ tính toán/trợ lí thông minh có thể tính nhanh biểu thức; HS đối chiếu với kết quả chương trình mình viết.\n⚠ HS kiểm tra lại kết quả; trung thực; giữ an toàn dữ liệu; đúng thời lượng dùng máy.","hs":"- HS dùng biểu thức trong chương trình; biết đối chiếu với công cụ tính thông minh; rèn tính chính xác."}]},{"lop":5,"mon":"Tin học","tuan":31,"tiet":31,"bai":"Bài 15: Sử dụng biểu thức trong chương trình (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Vận dụng biểu thức kết hợp với biến để tạo chương trình tính toán giải quyết nhiệm vụ.\n- Phát hiện, sửa lỗi và trình bày được chương trình có sử dụng biểu thức.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại khái niệm biểu thức; nêu nhiệm vụ thực hành.","hs":"- HS nhớ lại kiến thức, nhận nhiệm vụ."},{"ten":"2. Thực hành: Lập trình tính toán","gv":"- GV giao nhiệm vụ tạo chương trình tính (tổng điểm, trung bình, chu vi...).\n- Quan sát, hỗ trợ.","hs":"- HS tạo chương trình dùng biến và biểu thức, chạy thử."},{"ten":"3. Luyện tập: Sửa lỗi và hoàn thiện","gv":"- GV hướng dẫn HS kiểm tra, sửa lỗi biểu thức; hoàn thiện.","hs":"- HS sửa lỗi, hoàn thiện, trình bày chương trình."},{"ten":"4. Vận dụng","gv":"- GV gợi ý dùng biểu thức tính một đại lượng thực tế.","hs":"- HS nêu ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện chương trình dùng biến và biểu thức để tính toán.\n- (AI – nhận biết) GV nêu: máy tính và AI xử lí phép tính, dữ liệu nhanh và chính xác nhờ biểu thức và chương trình; con người kiểm tra và quyết định.\n⚠ HS trung thực; kiểm chứng kết quả; giữ an toàn dữ liệu.","hs":"- HS hoàn thiện chương trình tính toán; hiểu vai trò của biểu thức trong xử lí dữ liệu; rèn tính chính xác, trung thực."}]},{"lop":5,"mon":"Tin học","tuan":32,"tiet":32,"bai":"Bài 16: Từ kịch bản đến chương trình (Tiết 1)","yccd":"1. Năng lực Tin học (đặc thù):\n- Nêu được các bước chuyển một kịch bản/ý tưởng thành chương trình: mô tả, phân tích, viết chương trình, chạy thử.\n- Lập được kịch bản cho một chương trình đơn giản.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV giới thiệu ý tưởng làm một câu chuyện/trò chơi nhỏ trên máy tính.\n- Hỏi: cần chuẩn bị những gì trước khi lập trình?","hs":"- HS thảo luận, nêu các bước cần chuẩn bị."},{"ten":"2. Khám phá: Từ kịch bản đến chương trình","gv":"- GV hướng dẫn quy trình: viết kịch bản → xác định nhân vật, hành động → chọn cấu trúc lệnh → viết chương trình.\n- Minh hoạ bằng ví dụ.","hs":"- HS đọc SGK, nắm các bước; ghi nhớ kiến thức."},{"ten":"3. Thực hành: Lập kịch bản","gv":"- GV cho HS lập kịch bản cho một chương trình nhỏ (câu chuyện/trò chơi).\n- Quan sát, hỗ trợ.","hs":"- HS viết kịch bản: nhân vật, bối cảnh, các hành động theo thứ tự và điều kiện."},{"ten":"4. Luyện tập","gv":"- GV cho HS bắt đầu chuyển kịch bản thành các khối lệnh.","hs":"- HS ghép các khối lệnh đầu tiên theo kịch bản."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự lập kịch bản và bắt đầu chuyển thành chương trình trực quan.\n- (AI – nhận biết) GV cho HS quan sát công cụ AI có thể gợi ý ý tưởng kịch bản/nhân vật; HS tham khảo rồi tự phát triển ý tưởng của mình.\n⚠ GV kiểm soát công cụ AI; HS không nhập thông tin cá nhân; trung thực, ghi rõ nếu có dùng gợi ý của AI.","hs":"- HS lập kịch bản và khởi tạo chương trình; biết tham khảo gợi ý AI có chọn lọc và minh bạch; rèn tư duy sáng tạo."}]},{"lop":5,"mon":"Tin học","tuan":33,"tiet":33,"bai":"Bài 16: Từ kịch bản đến chương trình (Tiết 2)","yccd":"1. Năng lực Tin học (đặc thù):\n- Hoàn thiện được một chương trình từ kịch bản đã lập, phối hợp các cấu trúc tuần tự, lặp, rẽ nhánh, biến.\n- Trình bày, chia sẻ và tự đánh giá được sản phẩm chương trình.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV nhắc lại quy trình; nêu tiêu chí chương trình hoàn thiện.","hs":"- HS nhớ lại kịch bản, tiếp tục hoàn thiện."},{"ten":"2. Thực hành: Hoàn thiện chương trình","gv":"- GV hướng dẫn HS phối hợp các cấu trúc lệnh đã học để hoàn thiện chương trình theo kịch bản.\n- Quan sát, hỗ trợ.","hs":"- HS ghép lệnh, chạy thử, chỉnh sửa cho đúng kịch bản."},{"ten":"3. Luyện tập: Sửa lỗi và trình bày","gv":"- GV cho HS phát hiện, sửa lỗi; tổ chức trình bày sản phẩm.","hs":"- HS sửa lỗi, giới thiệu chương trình, giải thích cách làm."},{"ten":"4. Vận dụng – Chia sẻ","gv":"- GV tổ chức trưng bày sản phẩm; hướng dẫn nhận xét theo tiêu chí.","hs":"- HS chia sẻ sản phẩm; nhận xét bài bạn tích cực."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự hoàn thiện và chia sẻ một chương trình phối hợp nhiều cấu trúc lệnh.\n- (AI – nhận biết) GV hệ thống: AI có thể gợi ý ý tưởng, sửa lỗi, nhưng con người là người lập kịch bản, kiểm tra và chịu trách nhiệm về sản phẩm.\n⚠ HS trung thực về phần mình làm; tôn trọng sản phẩm của bạn; giữ an toàn dữ liệu; ứng xử có văn hoá khi chia sẻ.","hs":"- HS hoàn thiện và chia sẻ chương trình; hiểu vai trò và giới hạn của AI; trung thực, có trách nhiệm."}]},{"lop":5,"mon":"Tin học","tuan":34,"tiet":34,"bai":"Ôn tập học kì II","yccd":"1. Năng lực Tin học (đặc thù):\n- Hệ thống hoá kiến thức, kĩ năng học kì II: phần mềm đồ hoạ, cấu trúc tuần tự, lặp, rẽ nhánh, biến, biểu thức, từ kịch bản đến chương trình.\n- Vận dụng làm bài ôn tập và tự đánh giá kết quả học tập.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Khởi động","gv":"- GV tổ chức trò chơi hỏi – đáp nhanh ôn lại kiến thức lập trình đã học.","hs":"- HS tham gia trả lời, nhớ lại kiến thức."},{"ten":"2. Ôn tập kiến thức","gv":"- GV hệ thống kiến thức trọng tâm bằng sơ đồ tư duy; nhắc lại các cấu trúc lệnh.","hs":"- HS nhắc lại các cấu trúc: tuần tự, lặp, rẽ nhánh, biến, biểu thức."},{"ten":"3. Luyện tập tổng hợp","gv":"- GV cho HS làm bài/thực hành tổng hợp: tạo một chương trình nhỏ phối hợp các cấu trúc lệnh.","hs":"- HS làm bài, chạy thử, tự đánh giá và đánh giá bạn."},{"ten":"4. Vận dụng","gv":"- GV gợi ý HS nêu ý tưởng dùng lập trình/tin học vào học tập, đời sống.","hs":"- HS chia sẻ ý tưởng vận dụng."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự tạo lại một chương trình nhỏ phối hợp các cấu trúc đã học và giải thích.\n- (AI – nhận biết) GV hệ thống lại vai trò của AI như công cụ hỗ trợ trong tìm kiếm, sáng tạo, lập trình; nhấn mạnh kiểm chứng và trung thực.\n⚠ Nhắc lại quy tắc an toàn số: bảo vệ thông tin cá nhân, tôn trọng bản quyền, ứng xử có văn hoá, dùng máy đúng thời lượng.","hs":"- HS củng cố kĩ năng lập trình; hệ thống hiểu biết về vai trò và giới hạn của AI; ghi nhớ quy tắc an toàn số."}]},{"lop":5,"mon":"Tin học","tuan":35,"tiet":35,"bai":"Kiểm tra học kì II","yccd":"1. Năng lực Tin học (đặc thù):\n- Đánh giá được mức độ đạt yêu cầu cần đạt của học kì II về kiến thức, kĩ năng tin học và lập trình.\n- Vận dụng độc lập, trung thực làm bài kiểm tra.\n2. Năng lực chung:\n- Tự chủ và tự học: chủ động khám phá, thao tác trên máy tính, hoàn thành nhiệm vụ học tập.\n- Giao tiếp và hợp tác: tích cực trao đổi, làm việc nhóm, chia sẻ sản phẩm số.\n- Giải quyết vấn đề và sáng tạo: vận dụng kiến thức tin học vào tình huống thực tiễn.\n3. Phẩm chất:\n- Chăm chỉ: tích cực, tự giác luyện tập thao tác trên máy tính.\n- Trung thực: sử dụng thông tin, sản phẩm số trung thực, tôn trọng bản quyền.\n- Trách nhiệm: giữ gìn thiết bị, sử dụng máy tính và Internet an toàn, đúng cách, có văn hoá.","dodung":"- GV: Máy tính, máy chiếu, phòng máy (nếu có), bài giảng điện tử (PowerPoint), phần mềm/website minh hoạ, phiếu học tập.\n- HS: SGK Tin học 5 (Kết nối tri thức với cuộc sống), SBT, đồ dùng học tập.","hoatdong":[{"ten":"1. Ổn định – Hướng dẫn","gv":"- GV phổ biến hình thức, thời gian, yêu cầu bài kiểm tra (trắc nghiệm và/hoặc thực hành lập trình).","hs":"- HS lắng nghe, chuẩn bị làm bài."},{"ten":"2. Kiểm tra","gv":"- GV phát đề/giao nhiệm vụ thực hành; theo dõi, bảo đảm nghiêm túc.","hs":"- HS làm bài độc lập, trung thực."},{"ten":"3. Thu bài – Nhận xét","gv":"- GV thu bài/sản phẩm; nhận xét chung tinh thần, thái độ làm bài.","hs":"- HS nộp bài; rút kinh nghiệm."},{"ten":"4. Vận dụng","gv":"- GV gợi ý HS tiếp tục tìm hiểu, rèn kĩ năng tin học trong hè một cách an toàn, bổ ích.","hs":"- HS nêu dự định rèn luyện, khám phá."},{"ten":"5. Tích hợp Năng lực số & AI","gv":"- (Năng lực số – mức 2) HS tự thao tác hoàn thành phần thực hành (nếu có), lưu bài đúng quy định.\n- (AI – nhận biết) GV nhắc: khi kiểm tra, HS không dùng công cụ AI làm thay; phải tự lực, trung thực.\n⚠ Đề cao trung thực; không sao chép; giữ an toàn dữ liệu bài làm; dùng máy đúng mục đích.","hs":"- HS hoàn thành bài kiểm tra trung thực; không lệ thuộc AI; giữ an toàn dữ liệu."}]}];
